const mutationUpgradeDescriptions={"Spiked Membrane":["Grow defensive spikes. +8 contact damage.","Spikes lengthen and harden. +8 more contact damage.","Membrane becomes fully barbed. +8 more contact damage."],"Flagella":["Grow a swimming tail. +22% movement speed.","Strengthen the flagella. Another +22% movement speed.","Maximize flagellar thrust. Another +22% movement speed."],"Thick Membrane":["Thicken your outer membrane. +35 max HP and heal 35.","Add another protective membrane layer. +35 max HP and heal 35.","Complete the reinforced membrane. +35 max HP and heal 35."],"Regeneration":["Grow regenerative nodules. Recover 2 HP/sec.","Increase regenerative tissue. +2 additional HP/sec.","Maximize tissue repair. +2 additional HP/sec."],"Dense Cytoplasm":["Densify your cytoplasm. Reduce collision damage by 20%.","Further densify your cytoplasm. Another 20% collision resistance.","Reach maximum density. Another 20% collision resistance."],"Predatory Growth":["Increase body mass and gain +5 contact damage.","Grow larger again and gain another +5 contact damage.","Reach peak predatory size and gain another +5 contact damage."],"Acid Trail":["Secrete a short-lived corrosive slime trail. The trail fades quickly.","Acid becomes stronger and thicker, and the slime remains dangerous noticeably longer.","Create your strongest, thickest acid. The slime persists much longer before fading."],"Pseudopod Lash":["Grow an elastic attacking pseudopod: +5 damage, +10 reach and faster lashes.","Strengthen the lash: another +5 damage, +10 reach and faster recovery.","Perfect the whip: another +5 damage, +10 reach and fastest recovery."],"Clone Carapace":["Clones gain +20 max HP and 20% damage resistance.","Reinforce clone armor: +20 more HP and another 20% resistance.","Complete clone armor: +20 more HP and another 20% resistance."],"Raptor Flagella":["Clones hunt 28% faster.","Further strengthen clone flagella: another +28% speed.","Maximize clone flagella: another +28% speed."],"Clone Fangs":["Clones gain +5 contact damage.","Enlarge clone fangs: another +5 contact damage.","Perfect clone fangs: another +5 contact damage."],"Symbiotic Repair":["Clones regenerate 2 HP/sec.","Improve clone repair: +2 additional HP/sec.","Maximize clone repair: +2 additional HP/sec."],"Brood Expansion":["Increase clone capacity by 1.","Increase clone capacity by 1 again.","Increase clone capacity by 1 again.","Increase clone capacity by 1 again.","Reach maximum clone capacity."],"Spike Launcher":["Grow a hardened automatic spike launcher."]};function mutationChoiceDescription(m){const lv=m[3]?m[3]():0,a=mutationUpgradeDescriptions[m[0]];return a?(a[Math.min(lv,a.length-1)]||a[a.length-1]):m[1]}
const mutationCaps={"Spiked Membrane":3,"Flagella":3,"Thick Membrane":3,"Regeneration":3,"Dense Cytoplasm":3,"Predatory Growth":3,"Acid Trail":3,"Pseudopod Lash":3,"Mitosis":1,"Clone Carapace":3,"Raptor Flagella":3,"Clone Fangs":3,"Symbiotic Repair":3,"Brood Expansion":5};
function mutationLevel(name){if(name==="Spiked Membrane")return p.spikes;if(name==="Flagella")return p.flagella;if(name==="Thick Membrane")return p.membrane;if(name==="Regeneration")return Math.round(p.regen/2);if(name==="Dense Cytoplasm")return Math.round(p.armor/.2);if(name==="Predatory Growth")return p.growth;if(name==="Acid Trail")return p.acidTrail;if(name==="Pseudopod Lash")return p.lashLevel;if(name==="Mitosis")return p.cloneGene?1:0;if(name==="Clone Carapace")return Math.round(p.cloneArmor/.2);if(name==="Raptor Flagella")return Math.max(0,Math.round(Math.log(p.cloneSpeed/118)/Math.log(1.28)));if(name==="Clone Fangs")return Math.max(0,Math.round((p.cloneDamage-11)/5));if(name==="Symbiotic Repair")return Math.round(p.cloneRegen/2);if(name==="Brood Expansion")return p.cloneCount;return 0}
