function rewardOverlay(title,symbol,name,desc,button="CONTINUE"){active=false;const d=document.createElement("div");d.style.cssText="position:fixed;z-index:35;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(2,8,11,.82);backdrop-filter:blur(6px);padding:22px;text-align:center";d.innerHTML='<div style="width:min(390px,92vw);padding:24px 20px;border:1px solid rgba(160,255,220,.3);border-radius:24px;background:rgba(8,25,27,.94);box-shadow:0 0 45px rgba(91,255,200,.12)"><div style="font-size:11px;letter-spacing:3px;opacity:.65">'+title+'</div><div style="font-size:58px;margin:12px 0 4px">'+symbol+'</div><div style="font-size:27px;font-weight:900">'+name+'</div><div style="font-size:14px;line-height:1.5;opacity:.82;margin-top:10px">'+desc+'</div><button style="margin-top:22px;padding:13px 28px;border:0;border-radius:14px;font-weight:900;font-size:14px">'+button+'</button></div>';document.body.appendChild(d);return new Promise(resolve=>d.querySelector("button").onclick=()=>{d.remove();resolve()})}
function showSynergy(name,req){return rewardOverlay("SYNERGY FORMED",synergySymbols[name]||"✦",name,(req.map(x=>(mutationSymbols[x]||"◇")+" "+x).join(" + "))+"<br><br>"+(synergyDescriptions[name]||"Two completed adaptations have fused into a new biological effect."))}
let pauseLocks=0;
function lockGame(){pauseLocks++;active=false}
