const upgradeColors={"Spiked Membrane":"#d8fff1","Flagella":"#61d9e7","Thick Membrane":"#9fc9ff","Regeneration":"#9dffbd","Dense Cytoplasm":"#607f91","Predatory Growth":"#ff9b6b","Acid Trail":"#83e34f","Pseudopod Lash":"#63e6cf","Mitosis":"#c58cff","Clone Carapace":"#8ea6bb","Raptor Flagella":"#62d6ee","Clone Fangs":"#ff7c91","Symbiotic Repair":"#a8ffd1","Brood Expansion":"#d39cff","Spike Launcher":"#e5f4ff","Cannibalism":"#c87373","Emergency Mitosis":"#d8a5ff","Necrotic Burst":"#a96aff","Hypermetabolism":"#ffe36a","Predatory Membrane":"#ff766d"};
function buildItems(){const out=[];for(const m of [...mutations,...cloneMutations,...spikeMutations]){const lv=mutationLevel(m[0]);if(lv>0)out.push({name:m[0],lv,symbol:mutationSymbols[m[0]]||"◇",color:upgradeColors[m[0]]||"#72cfc1"})}for(const r of rareMutations)if(rareOwned.has(r[2]))out.push({name:r[0],lv:1,symbol:mutationSymbols[r[0]]||"◇",color:upgradeColors[r[0]]||"#d7b5ff"});for(const [name,req] of synergyDefs)if(synergies.has(name))out.push({name,lv:0,symbol:synergySymbols[name]||"✦",color:"#ffd96a",synergy:true,req});return out}
