async function checkSynergies(){const gained=[];for(const [name,req] of synergyDefs){if(synergies.has(name))continue;if(req.every(x=>mutationLevel(x)>=(mutationCaps[x]||99))){synergies.add(name);gained.push([name,req])}}if(gained.length){lockGame();updateBuildRow();for(const [name,req] of gained)await showSynergy(name,req);unlockGame();await resumeCountdown()}return gained.length}
function addInstability(n=1){instability+=n;const nt=Math.min(4,Math.floor(instability/6));if(nt>adaptationTier){adaptationTier=nt;announce("ECOSYSTEM ADAPTING","Instability "+instability+" — new counters are emerging.")}}
function grantRandomMutation(){const pool=[...mutations,...(p.cloneGene?cloneMutations:[])].filter(m=>!m[4]||m[3]()<m[4]);if(pool.length&&Math.random()<.82){const m=pool[Math.floor(Math.random()*pool.length)];m[2]();if(p.cloneGene&&cloneMutations.includes(m)&&clones.length<p.cloneCount)spawnClone();addInstability(1);return m[0]}const avail=rareMutations.filter(r=>!rareOwned.has(r[2]));if(avail.length){const r=avail[Math.floor(Math.random()*avail.length)];rareOwned.add(r[2]);announce("RARE MUTATION — "+r[0],r[1]);return r[0]}return "Stable Genome"}
function collectSuperBiomass(){active=false;const q=Math.random(),n=q<.55?1:q<.85?2:3,d=document.createElement("div");d.style.cssText="position:fixed;z-index:34;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(2,8,11,.84);backdrop-filter:blur(6px);padding:22px;text-align:center";d.innerHTML='<div style="width:min(400px,92vw)"><div style="font-size:11px;letter-spacing:4px;opacity:.68">SUPER BIOMASS</div><div style="font-size:25px;font-weight:900;margin:7px 0 18px">GENETIC LOTTERY</div><div id="reels" style="display:flex;gap:8px;justify-content:center"></div><div style="font-size:12px;opacity:.6;margin-top:15px">Analyzing unstable genome…</div></div>';document.body.appendChild(d);const reels=d.querySelector("#reels"),all=[...mutations,...cloneMutations,...spikeMutations].map(m=>m[0]).concat(rareMutations.map(r=>r[0]));for(let i=0;i<n;i++){const r=document.createElement("div");r.style.cssText="width:96px;height:112px;border:2px solid rgba(210,255,224,.42);border-radius:15px;background:rgba(11,31,32,.96);display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden";reels.appendChild(r)}let ticks=0;const spin=setInterval(()=>{ticks++;[...reels.children].forEach((r,i)=>{const nm=all[Math.floor(Math.random()*all.length)];r.innerHTML='<div style="font-size:38px">'+(mutationSymbols[nm]||"◇")+'</div><div style="font-size:9px;font-weight:800;margin-top:6px;padding:0 4px">'+nm+'</div>';r.style.transform='translateY('+(ticks%2?2:-2)+'px)'});sfx("food");if(ticks>=18){clearInterval(spin);const names=[],rewardDescs=[];for(let i=0;i<n;i++){const before=new Map([...mutations,...cloneMutations,...spikeMutations].map(m=>[m[0],m[3]?m[3]():0]));const nm=grantRandomMutation();names.push(nm);const mm=[...mutations,...cloneMutations,...spikeMutations].find(m=>m[0]===nm);rewardDescs.push(mm&&mutationUpgradeDescriptions[nm]?mutationUpgradeDescriptions[nm][Math.min(before.get(nm)||0,mutationUpgradeDescriptions[nm].length-1)]:mutationInfo(nm))}[...reels.children].forEach((r,i)=>{const nm=names[i];r.style.transform="none";r.style.borderColor="rgba(255,239,135,.85)";r.innerHTML='<div style="font-size:42px">'+(mutationSymbols[nm]||"◇")+'</div><div style="font-size:10px;font-weight:900;margin-top:6px;padding:0 4px">'+nm+'</div>'});d.querySelector("div>div:last-child").textContent="Genome locked.";setTimeout(async()=>{d.remove();for(let i=0;i<names.length;i++){const nm=names[i];await rewardOverlay("MUTATION ACQUIRED",mutationSymbols[nm]||"◇",nm,rewardDescs[i])}updateBuildRow();const formedSynergy=await checkSynergies();if(!formedSynergy)await resumeCountdown()},850)}},75)}
function spawnBloom(){const a=rnd(0,Math.PI*2),rr=rnd(150,Math.min(500,dish.r-90));bloom={x:p.x+Math.cos(a)*rr,y:p.y+Math.sin(a)*rr,r:105,t:22,threat:1,tick:0,spawn:0};announce("BIOMASS BLOOM","Enter the pulsing zone for richer biomass — staying raises its threat.")}
function updateBloom(dt){bloomClock-=dt;if(!bloom&&bloomClock<=0){spawnBloom();bloomClock=rnd(42,58)}if(!bloom)return;bloom.t-=dt;const inside=dist(p,bloom)<bloom.r-p.r*.3;if(inside){bloom.tick+=dt;bloom.spawn-=dt;if(bloom.spawn<=0){const a=rnd(0,6.28),rr=rnd(8,bloom.r*.8);food.push({x:bloom.x+Math.cos(a)*rr,y:bloom.y+Math.sin(a)*rr,r:rnd(4,6),phase:rnd(0,6.28),health:false});bloom.spawn=Math.max(.18,.55-bloom.threat*.07)}if(bloom.tick>5&&bloom.threat<5){bloom.tick=0;bloom.threat++;announce("BLOOM "+(bloom.threat===5?"OVERGROWN":"THREAT "+bloom.threat),"More biomass. More predators.");for(let i=0;i<bloom.threat;i++)addFoe()}}else bloom.tick=Math.max(0,bloom.tick-dt*.5);if(bloom.t<=0)bloom=null}
const mutationTraits={
"Spiked Membrane":{predatory:1,defensive:1},"Flagella":{mobility:2},"Thick Membrane":{defensive:2},"Regeneration":{regenerative:2},"Dense Cytoplasm":{defensive:2},"Predatory Growth":{predatory:2},"Acid Trail":{chemical:2},"Pseudopod Lash":{predatory:1,manipulator:1},"Mitosis":{colonial:2},"Clone Carapace":{colonial:1,defensive:1},"Raptor Flagella":{colonial:1,mobility:1},"Clone Fangs":{colonial:1,predatory:1},"Symbiotic Repair":{colonial:1,regenerative:1},"Brood Expansion":{colonial:2},"Spike Launcher":{predatory:2}
};
function commitMutation(name){const t=mutationTraits[name];if(!t)return;for(const k in t)lineage[k]=(lineage[k]||0)+t[k]}
function topLineage(n=3){return Object.entries(lineage).sort((a,b)=>b[1]-a[1]).slice(0,n)}
function lineageLabel(){return topLineage(2).filter(x=>x[1]>0).map(x=>x[0].toUpperCase()+" "+x[1]).join(" · ")||"UNCOMMITTED"}
function inheritedGenes(kind){const genes=[];if(kind==="striker"){if(p.spikes)genes.push("Spikes");if(p.lashLevel)genes.push("Pseudopod");if(p.spikeShooter)genes.push("Launcher")}if(kind==="propulsion"&&p.flagella)genes.push("Flagella");if(kind==="repair"&&p.regen)genes.push("Regeneration");if(kind==="chemical"&&p.acidTrail)genes.push("Acid");if(kind==="bulwark"){if(p.membrane)genes.push("Thick Membrane");if(p.armor)genes.push("Dense Cytoplasm")}return genes}
function colonyOptions(){const opts=[
 {kind:"striker",name:"STRIKER CELL",trait:"predatory",desc:"An offensive daughter cell. Inherits your spike, launcher and pseudopod genes.",color:"#65e8d0"},
 {kind:"propulsion",name:"PROPULSION CELL",trait:"mobility",desc:"A rear body segment specialized around Flagella and coordinated movement.",color:"#62d6ee"},
 {kind:"repair",name:"REPAIR CELL",trait:"regenerative",desc:"A regenerative segment that strengthens healing across the colony.",color:"#9dffbd"},
 {kind:"chemical",name:"SECRETION CELL",trait:"chemical",desc:"A chemical segment that inherits Acid Trail and widens corrosive secretion.",color:"#83e34f"},
 {kind:"bulwark",name:"BULWARK CELL",trait:"defensive",desc:"A durable outer segment specialized around membrane and cytoplasm defenses.",color:"#9fc9ff"}
 ];return opts.sort((a,b)=>(lineage[b.trait]||0)-(lineage[a.trait]||0)).slice(0,3)}
function chooseColonyForm(e){active=false;const d=document.createElement("div");d.style.cssText="position:fixed;z-index:24;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:rgba(2,10,12,.91);backdrop-filter:blur(6px);padding:22px;text-align:center";d.innerHTML='<div style="font-size:11px;letter-spacing:4px;opacity:.7">EVOLUTIONARY COMMITMENT</div><h2 style="margin:8px 0 3px">COLONY</h2><p style="max-width:390px;opacity:.8;margin:0 0 12px">Your mutation history determines which daughter-cell specializations are available.<br><small>'+lineageLabel()+'</small></p><div class="colonyChoices" style="display:grid;gap:10px;width:min(430px,94vw)"></div>';document.body.appendChild(d);const box=d.querySelector(".colonyChoices");for(const o of colonyOptions()){const genes=inheritedGenes(o.kind),b=document.createElement("button");b.className="card";b.style.borderColor=o.color;b.innerHTML='<b>'+o.name+'</b><small>'+o.desc+(genes.length?'<br><br>INHERITED: '+genes.join(" · "):'<br><br>Specialization can develop further with future mutations.')+'</small>';b.onclick=async()=>{sfx("evolve");bodySegments.push({kind:o.kind,name:o.name,color:o.color,genes,phase:0});if(o.kind==="striker")p.damage+=4;if(o.kind==="propulsion")p.speed*=1.08;if(o.kind==="repair")p.regen+=1;if(o.kind==="chemical")p.acidCellPower=1.2;if(o.kind==="bulwark"){p.max+=20;p.hp+=20}d.remove();showEvolution({...e,desc:"A daughter cell has permanently joined your body as a "+o.name.toLowerCase()+". Future evolution will build on this lineage."})};box.appendChild(b)}}
const evolutionStages=[
 {lv:10,name:"COLONY",desc:"Your first permanent daughter cell joins the organism.",r:3,hp:30,damage:3,colony:true},
 {lv:25,name:"MULTICELLULAR",desc:"Colony cells begin specializing into coordinated tissues and primitive organs.",r:5,hp:55,damage:6},
 {lv:45,name:"MICROFAUNA",desc:"Your tissues organize into a true microscopic animal body plan shaped by your lineage.",r:7,hp:85,damage:9},
 {lv:70,name:"DISHBREAKER",desc:"Your evolved body can no longer be contained by the petri dish.",r:8,hp:120,damage:13,escape:true}
];
function checkEvolution(){while(p.evoStage<evolutionStages.length&&p.lv>=evolutionStages[p.evoStage].lv){const e=evolutionStages[p.evoStage++];p.r+=e.r;p.max+=e.hp;p.hp=Math.min(p.max,p.hp+e.hp);p.damage+=e.damage;if(e.escape)breakDish(e);else if(e.colony)chooseColonyForm(e);else showEvolution(e)}}
function breakDish(e){sfx("break");active=false;breakFx={t:0,phase:0,e};glass=[];for(let i=0;i<46;i++){const a=rnd(0,Math.PI*2),d=rnd(12,Math.max(W,H)*.52),sz=rnd(5,18);glass.push({x:W/2+Math.cos(a)*d,y:H/2+Math.sin(a)*d,a,sz,v:rnd(70,230),spin:rnd(-5,5),rot:rnd(0,6.28)})}}
function finishEscape(){worldStage=1;breakFx=null;glass=[];food=[];foes=[];goo=[];clones=[];biomassDrops=[];spikeShots=[];bossShots=[];acidPools=[];p.r=Math.max(17,p.r*.55);dish.r=2200;p.x=dish.x;p.y=dish.y;for(let i=0;i<72;i++)addFood();for(let i=0;i<7;i++)addFoe();showEvolution({name:"THE OUTSIDE",desc:"The dish is gone. The world is enormous. Rotifers and worms give way to mites, springtails and insect larvae. Hunt, grow, evolve."})}
function showEvolution(e){sfx("evolve");active=false;const d=document.createElement("div");d.style.cssText="position:fixed;z-index:20;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(2,10,12,.72);backdrop-filter:blur(4px);padding:24px;text-align:center";d.innerHTML='<div style="max-width:390px"><div style="font-size:12px;letter-spacing:4px;opacity:.7">EVOLUTION</div><div style="font-size:34px;font-weight:900;margin:8px 0">'+e.name+'</div><div style="font-size:15px;line-height:1.45;opacity:.86">'+e.desc+'</div><button style="margin-top:22px;padding:13px 24px;border:0;border-radius:14px;font-weight:900;font-size:15px">CONTINUE</button></div>';document.body.appendChild(d);d.querySelector("button").onclick=()=>{d.remove();evolve()}}
const spikeMutations=[["Spike Launcher","Automatically fire a hardened membrane spike at the enemy closest to you within your visible targeting radius.",()=>{p.spikeShooter=true;p.spikeCd=0;p.targeting=1},()=>p.spikeShooter?1:0,1,"epic"]];const offensiveNames=new Set(["Spiked Membrane","Predatory Growth","Acid Trail","Pseudopod Lash","Clone Fangs","Spike Launcher"]);
function evolve(){active=false;ui.m.classList.remove("hidden");ui.cards.innerHTML="";const mitosis=mutations.find(m=>m[0]==="Mitosis"),pool=(p.cloneGene?[...mutations.filter(m=>m[0]!=="Mitosis"),...cloneMutations,...(p.spikes>=3&&!p.spikeShooter?spikeMutations:[])]:[mitosis]).filter(m=>m&&(!m[4]||m[3]()<m[4])),off=pool.filter(m=>offensiveNames.has(m[0]));let picks=p.cloneGene?pool.sort(()=>Math.random()-.5).slice(0,3):[mitosis];if(offenseMisses>=2&&off.length&&!picks.some(m=>offensiveNames.has(m[0]))){picks[picks.length-1]=off[Math.floor(Math.random()*off.length)];announce("OFFENSIVE ADAPTATION","An offensive mutation has been guaranteed.")}const hasOff=picks.some(m=>offensiveNames.has(m[0]));offenseMisses=hasOff?0:offenseMisses+1;picks.forEach(m=>{const b=document.createElement("button"),rarity=m[5]||"common";b.className="card rarity-"+rarity;const tier=m[4]?" <span class=\"tier-count\">"+m[3]()+"/"+m[4]+"</span>":"";b.innerHTML="<div class=\"rarity-label\">"+rarity.toUpperCase()+"</div><div style=\"font-size:27px;margin:3px 0\">"+(mutationSymbols[m[0]]||"◇")+"</div><b>"+m[0]+tier+"</b><small>"+mutationChoiceDescription(m)+"</small>";b.onclick=async()=>{audioOn();lockGame();sfx("upgrade");m[2]();commitMutation(m[0]);addInstability(1);if(p.cloneGene&&cloneMutations.includes(m)&&clones.length<p.cloneCount)spawnClone();ui.m.classList.add("hidden");updateBuildRow();const formedSynergy=await checkSynergies();unlockGame();if(!formedSynergy)await resumeCountdown()};ui.cards.appendChild(b)})}
function gooBurst(e){const color=e.elite?"#9b3158":"#d34f68";if(goo.length>180)goo.splice(0,goo.length-180);for(let i=0;i<(e.elite?18:10);i++){const a=rnd(0,Math.PI*2),v=rnd(35,145),life=rnd(.45,.9);goo.push({x:e.x,y:e.y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,r:rnd(2.5,6.5),life,max:life,color})}for(let i=0;i<(e.elite?6:3);i++){const a=rnd(0,Math.PI*2),d=rnd(0,e.r*.7),life=rnd(.65,1.05);goo.push({x:e.x+Math.cos(a)*d,y:e.y+Math.sin(a)*d,vx:Math.cos(a)*rnd(8,32),vy:Math.sin(a)*rnd(8,32),r:rnd(6,11),life,max:life,color})}}
