syncSettings();
function currentMutationEntries(){return buildItems().map(it=>{let text;if(it.synergy)text=(it.req||[]).map(x=>(mutationSymbols[x]||"◇")+" "+x).join(" + ")+"\n\n"+(synergyDescriptions[it.name]||"Combined adaptations create a new biological effect.");else{const m=[...mutations,...cloneMutations,...spikeMutations].find(x=>x[0]===it.name);const r=rareMutations.find(x=>x[0]===it.name);const arr=mutationUpgradeDescriptions[it.name];text=arr&&it.lv?arr.slice(0,Math.min(it.lv,arr.length)).map((x,i)=>"LEVEL "+(i+1)+": "+x).join("\n\n"):(m?m[1]:(r?r[1]:"Mutation effect."))}return {...it,text}})}
