currentMutationsBtn.onclick=()=>{renderMutationLibrary();pauseMenu.classList.add("hidden");mutationLibrary.classList.remove("hidden")};
mutationLibraryBack.onclick=()=>{mutationLibrary.classList.add("hidden");pauseMenu.classList.remove("hidden")};
mutationDetailBack.onclick=()=>{mutationDetail.classList.add("hidden");mutationLibrary.classList.remove("hidden")};
settingsBtn.onclick=()=>{settingsFromPause=false;startMenu.classList.add("hidden");settingsMenu.classList.remove("hidden");syncSettings()};pauseSettingsBtn.onclick=()=>{settingsFromPause=true;pauseMenu.classList.add("hidden");settingsMenu.classList.remove("hidden");syncSettings()};
settingsBack.onclick=()=>{settingsMenu.classList.add("hidden");if(settingsFromPause)pauseMenu.classList.remove("hidden");else startMenu.classList.remove("hidden")};
musicToggle.onclick=()=>{musicDisabled=!musicDisabled;localStorage.setItem("petriMusic",musicDisabled?"off":"on");syncSettings()};
audioToggle.onclick=()=>{audioDisabled=!audioDisabled;localStorage.setItem("petriAudio",audioDisabled?"off":"on");if(!audioDisabled)audioOn();applyAudio();syncSettings()};controlModeBtn.onclick=()=>{const modes=["left","right","touch","floating"];controlMode=modes[(modes.indexOf(controlMode)+1)%modes.length];localStorage.setItem("petriControls",controlMode);if(joy.id!==null)endControl({pointerId:joy.id});applyControlMode()};applyControlMode();
playBtn.onclick=async()=>{audioOn();startMenu.classList.add("hidden");pauseBtn.style.display="block";await resumeCountdown()};
pauseBtn.onclick=()=>{if(!active)return;lockGame();pauseMenu.classList.remove("hidden");pauseBtn.style.display="none"};
const colonyCellsBtn=$("#colonyCellsBtn"),colonyCellsMenu=$("#colonyCellsMenu"),colonyCellsList=$("#colonyCellsList"),colonyCellsBack=$("#colonyCellsBack");
function colonyCellInfo(seg){if(seg.kind==="striker")return "<b>COMBAT:</b> +4 parent contact damage.<br><b>Inherited attacks:</b> "+(seg.genes.length?seg.genes.join(" · "):"None yet")+".<br><b>Role:</b> offensive tissue; future attacks will originate from this segment.";
if(seg.kind==="propulsion")return "<b>MOVEMENT:</b> +8% organism movement speed.<br><b>Inherited:</b> "+(seg.genes.length?seg.genes.join(" · "):"No Flagella inherited")+".<br><b>Role:</b> propulsion tissue.";
if(seg.kind==="repair")return "<b>REGENERATION:</b> +1 HP/sec to the organism.<br><b>Inherited:</b> "+(seg.genes.length?seg.genes.join(" · "):"No Regeneration inherited")+".<br><b>Role:</b> repair/support tissue.";
if(seg.kind==="chemical")return "<b>ACID:</b> Acid Trail originates from this cell and deals +20% damage.<br><b>Inherited:</b> "+(seg.genes.length?seg.genes.join(" · "):"No Acid Trail inherited yet")+".<br><b>Role:</b> chemical secretion tissue.";
if(seg.kind==="bulwark")return "<b>DURABILITY:</b> +20 maximum HP when formed.<br><b>Inherited:</b> "+(seg.genes.length?seg.genes.join(" · "):"No defensive gene inherited")+".<br><b>Role:</b> protective outer tissue.";
return "Specialized daughter cell."}
function renderColonyCells(){colonyCellsList.innerHTML="";if(!bodySegments.length){colonyCellsList.innerHTML='<div style="opacity:.72;padding:18px">No permanent daughter cells yet. Reach COLONY to form one.</div>';return}bodySegments.forEach((seg,i)=>{const d=document.createElement("div");d.className="card";d.style.borderColor=seg.color;d.innerHTML='<div style="display:flex;align-items:center;gap:10px"><span style="width:28px;height:28px;border-radius:50%;background:'+seg.color+';box-shadow:inset 3px 3px 7px #fff6,0 2px 8px #0005;flex:0 0 auto"></span><b>'+(i+1)+'. '+seg.name+'</b></div><small style="margin-top:8px;line-height:1.45">'+colonyCellInfo(seg)+'</small>';colonyCellsList.appendChild(d)})}
colonyCellsBtn.onclick=()=>{renderColonyCells();pauseMenu.classList.add("hidden");colonyCellsMenu.classList.remove("hidden")};
colonyCellsBack.onclick=()=>{colonyCellsMenu.classList.add("hidden");pauseMenu.classList.remove("hidden")};
const pauseRestartBtn=$("#pauseRestartBtn");pauseRestartBtn.onclick=()=>{audioOn();location.reload()};
resumeBtn.onclick=async()=>{pauseMenu.classList.add("hidden");pauseBtn.style.display="block";unlockGame();await resumeCountdown()};
$("#restart").onclick=()=>location.reload();lastFrameAt=performance.now();rafId=requestAnimationFrame(loop);